const p = msg.payload;
if (!p || typeof p !== 'object') {
    node.error('Payload MQTT não é um objeto JSON', msg);
    return null;
}

const deviceId = String(p.device_id || '').trim();
const temp = Number(p.temp);
const humidity = Number(p.umid);
const heatIndex = p.ic === undefined || p.ic === null ? null : Number(p.ic);
const rssi = p.rssi === undefined || p.rssi === null ? null : Number(p.rssi);

if (!/^[a-zA-Z0-9_-]{1,64}$/.test(deviceId)) {
    node.error('device_id ausente ou inválido', msg);
    return null;
}
// Tópico fdctmon/{device_id}/data. A ACL do broker só deixa cada cliente
// publicar no ramo do próprio client-id; o payload precisa concordar com ele.
const partes = String(msg.topic || '').split('/');
if (partes.length !== 3 || partes[1] !== deviceId) {
    node.error('device_id do payload difere do tópico', msg);
    return null;
}
if (!Number.isFinite(temp) || temp < -40 || temp > 80) {
    node.error('temperatura fora da faixa válida', msg);
    return null;
}
if (!Number.isFinite(humidity) || humidity < 0 || humidity > 100) {
    node.error('umidade fora da faixa válida', msg);
    return null;
}
if (heatIndex !== null && !Number.isFinite(heatIndex)) {
    node.error('índice de calor inválido', msg);
    return null;
}
if (rssi !== null && (!Number.isFinite(rssi) || rssi < -120 || rssi > 0)) {
    node.error('RSSI fora da faixa válida', msg);
    return null;
}

// Local e nome vêm do cadastro mantido pela página /admin/. Placa sem cadastro
// continua gravando, com local "sem-local" e o próprio device_id como nome.
const cadastro = global.get('cadastro');
const dispositivos = (cadastro && cadastro.dispositivos) || {};
const registro = Object.prototype.hasOwnProperty.call(dispositivos, deviceId)
    ? dispositivos[deviceId]
    : {};
const local = registro.local || 'sem-local';
const nome = registro.nome || deviceId;

// Última leitura de cada placa, mostrada na página de cadastro. Fica só em
// memória: depois de um reinício, cada placa reaparece no ciclo seguinte.
// Objeto sem protótipo e com teto: client-ids arbitrários de quem tem a
// credencial da frota não crescem a memória sem limite.
const MAX_VISTOS = 1000;
const vistos = global.get('vistos') || Object.create(null);
if (!Object.prototype.hasOwnProperty.call(vistos, deviceId) && Object.keys(vistos).length >= MAX_VISTOS) {
    let maisAntigo = null;
    for (const id of Object.keys(vistos)) {
        if (maisAntigo === null || vistos[id].ultimo < vistos[maisAntigo].ultimo) maisAntigo = id;
    }
    delete vistos[maisAntigo];
}
vistos[deviceId] = {
    ultimo: Date.now(),
    temp,
    umid: humidity,
    rssi,
    firmware: p.firmware_version ? String(p.firmware_version).slice(0, 32) : null
};
global.set('vistos', vistos);

// O nó InfluxDB escapa tags e fields e recebe o measurement da própria configuração.
const fields = { temperatura: temp, umidade: humidity };
if (heatIndex !== null) fields.indice_calor = heatIndex;
if (rssi !== null) fields.rssi = rssi;
const tags = {
    device_id: deviceId,
    sensor: String(p.sensor || 'desconhecido').slice(0, 32),
    local,
    nome
};

node.status({ fill: 'green', shape: 'dot', text: `${nome}: ${temp} °C / ${humidity} %` });

// Saída 1 grava no InfluxDB; saída 2 leva uma cópia própria ao Zabbix,
// com o device_id porque ele é o nome do host no Zabbix.
return [
    { ...msg, payload: [fields, tags] },
    { ...msg, payload: { device_id: deviceId, ...fields } }
];

// O nó zabbix-sender chama addItem(...item): cada item precisa ser um array
// [host, chave, valor]. Um array de objetos {host, key, value} é aceito sem
// erro e chega ilegível ao Zabbix, então o formato abaixo é obrigatório.
//
// O host é o próprio device_id: no Zabbix existe um host homônimo por
// dispositivo (ex.: esp32-18B4C0D8CBB0). As chaves à direita são os itens
// trapper desse host; `headindex` reproduz a grafia cadastrada no Zabbix.
const CHAVES = {
    temperatura: 'temp',
    umidade: 'umid',
    indice_calor: 'headindex',
    rssi: 'rssi'
};

const medicao = msg.payload;
const host = medicao.device_id;

const itens = Object.entries(CHAVES)
    .filter(([campo]) => medicao[campo] !== undefined && medicao[campo] !== null)
    .map(([campo, chave]) => [host, chave, String(medicao[campo])]);

if (itens.length === 0) {
    node.error('Nenhum item válido para enviar ao Zabbix', msg);
    return null;
}

node.status({ fill: 'green', shape: 'dot', text: `${host}: ${itens.length} itens` });
msg.payload = itens;
return msg;

// Primeira subida: sem dispositivos.json, cria um cadastro vazio no disco.
// Qualquer outro erro de leitura (permissão, diretório ausente) deixa o
// cadastro descarregado e a página mostra o motivo.
const detalhe = String((msg.error && msg.error.message) || 'erro desconhecido');
if (!/ENOENT/.test(detalhe)) {
    const t = `Não foi possível ler dispositivos.json: ${detalhe}`;
    global.set('cadastroErro', t);
    node.status({ fill: 'red', shape: 'ring', text: 'falha ao ler o cadastro' });
    node.error(t);
    return null;
}
node.warn('dispositivos.json ausente; criando cadastro vazio.');
node.status({ fill: 'blue', shape: 'dot', text: 'cadastro vazio criado' });
return {
    origem: 'inicial',
    payload: { schema_version: 1, revisao: 0, locais: {}, dispositivos: {} }
};

msg.headers = { 'Cache-Control': 'no-store' };
msg.payload = {
    cadastro: global.get('cadastro') || null,
    erro: global.get('cadastroErro') || null,
    vistos: global.get('vistos') || {},
    agora: Date.now()
};
return msg;

// Valida e normaliza o cadastro vindo do disco (origem "arquivo" ou "inicial")
// ou da página /admin/ (origem "api").
// Saída 1: cadastro válido em msg.cadastro. Saída 2: erro HTTP (só origem "api").
const SLUG = /^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/;
const DEVICE = /^[a-zA-Z0-9_-]{1,64}$/;
const CONTROLE = /[\u0000-\u001f\u007f]/;
const MAX_LOCAIS = 200;
const MAX_DISPOSITIVOS = 2000;

const origem = msg.origem || 'arquivo';

function ehObjeto(v) {
    return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function texto(valor, max) {
    if (typeof valor !== 'string') return null;
    const t = valor.trim();
    if (t.length === 0 || t.length > max || CONTROLE.test(t)) return null;
    return t;
}

function vazio(v) {
    return v === undefined || v === null || v === '';
}

function validar(c) {
    if (!ehObjeto(c)) return { erro: 'O cadastro precisa ser um objeto JSON.' };
    const locaisIn = c.locais === undefined ? {} : c.locais;
    const dispIn = c.dispositivos === undefined ? {} : c.dispositivos;
    if (!ehObjeto(locaisIn)) return { erro: 'O campo "locais" precisa ser um objeto.' };
    if (!ehObjeto(dispIn)) return { erro: 'O campo "dispositivos" precisa ser um objeto.' };

    const idsLocais = Object.keys(locaisIn);
    if (idsLocais.length > MAX_LOCAIS) return { erro: `Máximo de ${MAX_LOCAIS} locais.` };
    // Mapas sem protótipo: chaves como "__proto__" viram dados comuns.
    const locais = Object.create(null);
    for (const id of idsLocais) {
        if (!SLUG.test(id) || id === 'sem-local') {
            return { erro: `Código de local inválido: "${id}". Use letras minúsculas, números e hífen, até 32 caracteres.` };
        }
        const nome = texto(locaisIn[id], 48);
        if (!nome) return { erro: `O nome do local "${id}" está vazio ou passa de 48 caracteres.` };
        locais[id] = nome;
    }

    const idsDisp = Object.keys(dispIn);
    if (idsDisp.length > MAX_DISPOSITIVOS) return { erro: `Máximo de ${MAX_DISPOSITIVOS} dispositivos.` };
    const dispositivos = Object.create(null);
    for (const id of idsDisp) {
        if (!DEVICE.test(id)) return { erro: `Identificador de dispositivo inválido: "${id}".` };
        const d = dispIn[id];
        if (!ehObjeto(d)) return { erro: `O registro do dispositivo "${id}" precisa ser um objeto.` };
        const registro = {};
        if (!vazio(d.nome)) {
            const nome = texto(d.nome, 64);
            if (!nome) return { erro: `O nome do dispositivo "${id}" é inválido ou passa de 64 caracteres.` };
            registro.nome = nome;
        }
        if (!vazio(d.local)) {
            if (typeof d.local !== 'string' || !Object.prototype.hasOwnProperty.call(locais, d.local)) {
                return { erro: `O dispositivo "${id}" aponta para o local "${d.local}", que não existe.` };
            }
            registro.local = d.local;
        }
        dispositivos[id] = registro;
    }

    const revisao = Number.isInteger(c.revisao) && c.revisao >= 0 ? c.revisao : 0;
    return { cadastro: { schema_version: 1, revisao, locais, dispositivos } };
}

function falhar(status, mensagem) {
    if (origem !== 'api') {
        const t = `dispositivos.json rejeitado: ${mensagem}`;
        global.set('cadastroErro', t);
        node.status({ fill: 'red', shape: 'ring', text: 'cadastro inválido no disco' });
        node.error(t, msg);
        return null;
    }
    msg.statusCode = status;
    msg.headers = { 'Cache-Control': 'no-store' };
    msg.payload = { erro: mensagem };
    return [null, msg];
}

let entrada = msg.payload;
if (Buffer.isBuffer(entrada)) entrada = entrada.toString('utf8');
if (typeof entrada === 'string') {
    try {
        entrada = JSON.parse(entrada);
    } catch (e) {
        return falhar(400, `JSON inválido: ${e.message}`);
    }
}

const resultado = validar(entrada);
if (resultado.erro) return falhar(400, resultado.erro);

if (origem === 'api') {
    const atual = global.get('cadastro');
    if (!atual) {
        return falhar(503, 'O cadastro não foi carregado do disco. Corrija dispositivos.json no host e reinicie o Node-RED.');
    }
    if (resultado.cadastro.revisao !== atual.revisao) {
        return falhar(409, 'O cadastro foi alterado em outra janela. Recarregue a página antes de salvar.');
    }
    resultado.cadastro.revisao = atual.revisao + 1;
}

msg.cadastro = resultado.cadastro;
return [msg, null];

// Grava (quando preciso) e aplica o cadastro validado, tudo de forma síncrona:
// duas requisições não se intercalam aqui, então a revisão conferida abaixo
// é definitiva. A gravação é atômica: arquivo temporário + rename, com o
// conteúdo anterior preservado em dispositivos.json.bak.
const ARQUIVO = '/data/cadastro/dispositivos.json';
const c = msg.cadastro;

function responder(status, payload) {
    if (msg.origem !== 'api') return null;
    msg.statusCode = status;
    msg.headers = { 'Cache-Control': 'no-store' };
    msg.payload = payload;
    return msg;
}

if (msg.origem === 'api') {
    const atual = global.get('cadastro');
    if (!atual || c.revisao !== atual.revisao + 1) {
        return responder(409, { erro: 'O cadastro foi alterado em outra janela. Recarregue a página antes de salvar.' });
    }
}

// O cadastro lido do disco já está gravado; os demais são gravados antes de valer.
if (msg.origem !== 'arquivo') {
    const temporario = `${ARQUIVO}.tmp`;
    try {
        fs.writeFileSync(temporario, JSON.stringify(c, null, 2) + '\n', { encoding: 'utf8', mode: 0o640 });
        if (fs.existsSync(ARQUIVO)) fs.copyFileSync(ARQUIVO, `${ARQUIVO}.bak`);
        fs.renameSync(temporario, ARQUIVO);
    } catch (e) {
        const t = `Não foi possível gravar dispositivos.json: ${e.message}`;
        node.status({ fill: 'red', shape: 'ring', text: 'falha ao gravar o cadastro' });
        node.error(t, msg);
        if (msg.origem !== 'api') {
            global.set('cadastroErro', t);
            return null;
        }
        return responder(500, { erro: `${t}. Confira se o diretório do cadastro no host pertence ao UID 1000.` });
    }
}

global.set('cadastro', c);
global.set('cadastroErro', null);
const nDisp = Object.keys(c.dispositivos).length;
const nLocais = Object.keys(c.locais).length;
node.status({ fill: 'green', shape: 'dot', text: `rev. ${c.revisao}: ${nDisp} dispositivos, ${nLocais} locais` });

return responder(200, { ok: true, revisao: c.revisao });
